import {GameSession} from './engine.js';
import {LocalTransport} from './transport.js';
import {questions} from './questions.js';
import {tiles} from './combo.js';
import {timing} from './config.js';
const $=s=>document.querySelector(s);
const reduced=matchMedia('(prefers-reduced-motion: reduce)');
const escape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let transport,state,timer,busy=false,version=0,lobby=true,pulse=()=>{};
import('./field.js').then(m=>pulse=m.pulse).catch(()=>{});
const icon=(kind)=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" aria-hidden="true">${kind==='human'?'<circle cx="12" cy="7" r="4"/><path d="M4 22v-3a8 8 0 0 1 16 0v3"/>':kind==='ai'?'<rect x="3" y="6" width="18" height="15" rx="4"/><path d="M12 2v4M7 12h2m6 0h2M8 17h8"/>':kind==='coin'?'<circle cx="12" cy="12" r="9"/><path d="M14 8h-3a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4h-3m2-10v12"/>':'<path d="m12 2 3 6 7 1-5 5 1 7-6-3-6 3 1-7-5-5 7-1Z"/>'}</svg>`;
const avatar=i=>`<span class="avatar">${icon(i?'ai':'human')}</span>`;
const metric=(kind,value)=>`<span class="metric ${kind}" aria-label="${kind==='coin'?'Кредити':'Точки'}: ${value}" title="${kind==='coin'?'Кредити':'Точки'}">${icon(kind)}<b>${value}</b></span>`;
const tileById=id=>tiles.find(t=>t.id===id);
function slots(player){return player.tiles.length?`<div class="slots">${player.tiles.map(t=>`<div class="slot" data-tile-id="${t.id}"><span class="tile-icon">${tileById(t.id).icon}</span><div><b>${tileById(t.id).name}</b><p>${tileById(t.id).desc}${t.topic?' · '+escape(t.topic):''}</p></div></div>`).join('')}</div>`:'';}
const countdown=()=>'<div class="countdown" aria-label="Оставащи секунди"><span aria-hidden="true">◷</span> <b id="timer"></b></div><div class="progress"><i id="bar"></i></div>';
function time(seconds,expire){clearInterval(timer);const deadline=Date.now()+seconds*1000;const tick=()=>{const left=Math.max(0,deadline-Date.now());if($('#timer'))$('#timer').textContent=Math.ceil(left/1000);if($('#bar'))$('#bar').style.transform=`scaleX(${left/(seconds*1000)})`;if(!left){clearInterval(timer);expire();}};timer=setInterval(tick,timing.clockTick*1000);tick();}
function send(action){if(busy)return;clearInterval(timer);pulse();transport.send(action);}
function boot(){++version;clearInterval(timer);transport?.close();lobby=true;state=null;transport=new LocalTransport(new GameSession());transport.subscribe(render);}
const pause=seconds=>new Promise(resolve=>setTimeout(resolve,seconds*1000));
async function answer(value){if(busy||state.phase!=='quiz')return;busy=true;clearInterval(timer);const current=version;$('#stage').inert=true;$(`[data-answer="${value}"]`)?.classList.add('selected');pulse();
 // Resolve once now; keep the selected answer visible before showing results.
 const result=transport.session.dispatch({type:'answer',answer:value});
 result.activated[0].forEach(t=>{const el=$(`[data-tile-id="${t.id}"]`);if(el&&!reduced.matches)el.animate([{transform:'scale(1)',opacity:1},{transform:'scale(1.12)',background:'#71954c',opacity:1},{transform:'scale(1.2)',opacity:0}],{duration:timing.tileFlash*1000,fill:'forwards'});});
 await pause(timing.answerDelay);if(version!==current)return;render(result);
}
async function render(s){const current=++version;clearInterval(timer);busy=true;const stage=$('#stage');stage.inert=true;
 if(state&&!reduced.matches)await stage.animate([{opacity:1},{opacity:0}],{duration:timing.exitAnimation*1000}).finished.catch(()=>{});
 if(current!==version)return;state=s;const q=questions[s.round-1],me=s.players[0];document.body.dataset.phase=lobby?'lobby':s.phase;
 $('#scores').innerHTML=lobby?'':s.players.map((p,i)=>`<div class="player ${i?'nova':''}">${avatar(i)}<b class="player-name">${escape(p.name)}</b><div class="metrics">${metric('coin',p.credits)}${metric('points',p.score)}</div></div>`).join('');
 if(lobby){stage.innerHTML=`<form class="lobby"><span class="hero-symbol" aria-hidden="true">✳</span><h1>Комбо</h1><input id="player-name" aria-label="Твоето име" placeholder="Играч 1" maxlength="24" autocomplete="nickname"><button class="primary" type="submit">${icon('ai')} Игра с Nova AI</button><button type="button" disabled title="Очаквайте скоро">${icon('human')} Игра с приятели <small>Скоро</small></button></form>`;$('.lobby').onsubmit=e=>{e.preventDefault();if(busy)return;const name=$('#player-name').value;lobby=false;enterFullscreen();send({type:'enter',name});};}
 else if(s.phase==='ready'){stage.innerHTML=`<div class="topic-screen"><p>${s.round===1?'Тема:':'Следваща тема:'}</p><h1>${escape(q.topic)}</h1>${me.tiles.some(t=>t.id==='converter')?'<label class="convert"><input id="convert" type="checkbox"> ⚡ Конвертор: 2 кредита → +1 точка</label>':''}</div>${countdown()}`;}
 else if(s.phase==='quiz'){stage.innerHTML=`<div class="stage-top"><b>${escape(q.topic)}</b><span>${s.round} / ${questions.length}</span></div><div class="battle-loadout">${slots(me)}</div><div class="question-card"><h2>${escape(q.text)}</h2></div><div class="answers">${q.answers.map((a,i)=>`<button class="answer" data-answer="${i}"><span class="answer-letter">${i+1}</span><b>${escape(a)}</b></button>`).join('')}</div>${countdown()}`;stage.querySelectorAll('[data-answer]').forEach(b=>b.onclick=()=>answer(Number(b.dataset.answer)));}
 else if(s.phase==='result'){const delta=s.rewards[0].points-s.rewards[1].points;stage.innerHTML=`<h2 class="screen-title">${delta===0?'Равенство в рунда':escape(s.players[delta>0?0:1].name)+' печели рунда'}</h2><div class="result-players">${s.players.map((p,i)=>`<article class="result-player ${i?'nova':''}"><div class="result-name">${avatar(i)}<b>${escape(p.name)}</b></div><div class="answer-verdict ${s.answers[i]===q.correct?'correct':'wrong'}">${s.answers[i]===null?'Без отговор':(s.answers[i]===q.correct?'✓ Верен отговор':'✕ Грешен отговор')}</div><p class="chosen-answer">${s.answers[i]===null?'—':escape(q.answers[s.answers[i]])}</p><div class="reward">${metric('points','+'+s.rewards[i].points)}${metric('coin',(s.rewards[i].credits>=0?'+':'')+s.rewards[i].credits)}</div><div class="bonuses">${s.activated[i].map(t=>`<div class="bonus"><span class="tile-icon">${tileById(t.id).icon}</span><b>${tileById(t.id).name}</b><span>${t.points?'+'+t.points+' т.':''}${t.credits?' '+(t.credits>0?'+':'')+t.credits+' кредита':''}</span></div>`).join('')}</div></article>`).join('')}</div><div class="correct-answer"><span>Верен отговор</span><b>✓ ${escape(q.answers[q.correct])}</b></div>${countdown()}`;}
 else if(s.phase==='market'){stage.innerHTML=`<h2 class="screen-title">Избери плочка</h2><div class="bid-controls"><label>Оферта ${icon('coin')}<input id="amount" aria-label="Оферта в кредити" type="number" min="1" max="${me.credits}" value="1" ${me.credits<1?'disabled':''}></label>${me.tiles.length===3?`<label>Замени <select id="slot">${me.tiles.map((t,i)=>`<option value="${i}">${tileById(t.id).name}</option>`).join('')}</select></label>`:''}${s.market.some(t=>t.id==='focus')?`<label>Тема за Фокус <select id="focus">${[...new Set(questions.map(q=>q.topic))].map(t=>`<option>${escape(t)}</option>`).join('')}</select></label>`:''}</div><div class="market">${s.market.map((t,i)=>`<button class="shop-card" data-tile="${i}" ${me.tiles.some(x=>x.id===t.id)||me.credits<1?'disabled':''}><b>${t.name}</b><p>${t.desc}</p><span class="tile-icon">${t.icon}</span>${me.tiles.some(x=>x.id===t.id)?'<small>Притежаваш</small>':''}</button>`).join('')}</div><div class="market-bottom"><p>Натисни плочка, за да изпратиш офертата. Най-високата печели.</p><button id="skip">Пропусни →</button></div><p id="error" role="alert"></p>${countdown()}`;
 stage.querySelectorAll('[data-tile]').forEach(b=>b.onclick=()=>{if(busy)return;const amount=Number($('#amount').value);if(!Number.isInteger(amount)||amount<1||amount>me.credits){$('#error').textContent='Въведи цяло число от 1 до '+me.credits+'.';$('#amount').focus();return;}send({type:'bid',tile:Number(b.dataset.tile),amount,slot:Number($('#slot')?.value||0),topic:$('#focus')?.value});});$('#skip').onclick=()=>send({type:'bid'});}
 else if(s.phase==='reveal'){stage.innerHTML=`<h2 class="screen-title">Нови плочки</h2><div class="purchase-players">${s.players.map((p,i)=>{const bid=s.bids[i],tile=s.market[bid.tile];return `<article class="purchase-player ${i?'nova':''}"><div class="result-name">${avatar(i)}<b>${escape(p.name)}</b></div>${tile?`<div class="purchase-tile"><b>${tile.name}</b><p>${tile.desc}</p><span class="tile-icon">${tile.icon}</span></div><div class="purchase-verdict ${s.purchased[i]?'correct':''}">${s.purchased[i]?'✓ Получава плочката':s.bids[1-i].tile===bid.tile&&s.bids[1-i].amount===bid.amount?'Равни оферти · без покупка':'По-ниска оферта · без покупка'}</div><div class="bid-value">Оферта ${metric('coin',bid.amount)}</div>`:'<p class="purchase-verdict">Пропусна</p>'}</article>`;}).join('')}</div>${countdown()}`;}
 else if(s.phase==='finished'){const delta=me.score-s.players[1].score;stage.innerHTML=`<div class="topic-screen"><p>Краен резултат</p><h1>${delta===0?'Равенство':escape(s.players[delta>0?0:1].name)+' печели'}</h1><div class="final-score">${s.players.map((p,i)=>`<div class="${i?'nova':''}"><span>${escape(p.name)}</span>${metric('points',p.score)}</div>`).join('')}</div><button class="primary" id="again">Нов дуел ↻</button></div>`;$('#again').onclick=boot;}
 if(!reduced.matches)await stage.animate([{opacity:0,transform:'translateY(8px)'},{opacity:1,transform:'translateY(0)'}],{duration:timing.enterAnimation*1000,easing:'cubic-bezier(.16,1,.3,1)'}).finished.catch(()=>{});
 if(current!==version)return;busy=false;stage.inert=false;if(lobby)return;
 if(s.phase==='ready')time(timing.topic,()=>send({type:'start',convert:$('#convert')?.checked}));
 if(s.phase==='quiz')time(timing.question,()=>answer(null));
 if(s.phase==='market')time(timing.market,()=>send({type:'bid'}));
 if(s.phase==='result')time(timing.result,()=>send({type:'continue'}));
 if(s.phase==='reveal')time(timing.newTiles,()=>send({type:'continue'}));
}
function updateFullscreen(){const full=!!document.fullscreenElement,b=$('#fullscreen');b.setAttribute('aria-label',full?'Изход от цял екран':'На цял екран');b.title=b.getAttribute('aria-label');b.innerHTML=`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" aria-hidden="true"><path d="${full?'M3 8h5V3m13 5h-5V3M8 21v-5H3m13 5v-5h5':'M8 3H3v5m13-5h5v5M3 16v5h5m13-5v5h-5'}"/></svg>`;}
async function enterFullscreen(){if(document.fullscreenElement)return;try{await document.documentElement.requestFullscreen();}catch{$('#fullscreen-note').textContent='Играта запълва прозореца. Цял екран не е разрешен от браузъра.';$('#fullscreen-note').hidden=false;setTimeout(()=>$('#fullscreen-note').hidden=true,timing.fullscreenNotice*1000);}}
$('#fullscreen').onclick=async()=>{if(document.fullscreenElement){try{await document.exitFullscreen();}catch{}}else await enterFullscreen();};document.addEventListener('fullscreenchange',updateFullscreen);updateFullscreen();
$('#rules').onclick=()=>{$('#help-content').innerHTML=`<p>8 рунда срещу NOVA. Започваш с 3 кредита.</p><p><b>Въпрос · ${timing.question} секунди</b><br>Натисни отговор или клавиш 1–4. Верен: +1 точка и +2 кредита. Грешен или пропуснат: +1 кредит.</p><p><b>Тайна оферта · ${timing.market} секунди</b><br>Настрой сумата и натисни плочка. Най-високата оферта печели. При равни оферти никой не плаща.</p><p><b>До 3 различни плочки</b><br>Действат от следващия рунд. При пълен комплект избери коя да замениш. В рундове 7 и 8 няма пазар.</p><p>Темата се показва за ${timing.topic} секунди, резултатът за ${timing.result}, а новите плочки за ${timing.newTiles}. Печели играчът с повече точки.</p>`;$('#help').showModal();};$('#close-help').onclick=$('#help-ok').onclick=()=>$('#help').close();
$('#restart').onclick=()=>{if(lobby||confirm('Да започнем нов дуел? Текущият резултат ще се изчисти.'))boot();};
document.addEventListener('keydown',e=>{if($('#help').open||e.repeat||['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName))return;const i='1234'.indexOf(e.key);if(state?.phase==='quiz'&&i>=0)answer(i);});boot();
